mapper.select:
SELECT DISTINCT v.embedding_model_id AS model_id, v.embedding_provider AS provider, v.embedding_model AS model, v.embedding_dimensions AS dimensions FROM document_versions v JOIN documents d ON d.active_version_id = v.id JOIN knowledge_bases kb ON kb.id = d.knowledge_base_id WHERE v.status IN ('READY', 'PROCESSING') AND EXISTS (SELECT 1 FROM users u WHERE u.id = kb.owner_id AND u.role = 'ADMIN') AND d.knowledge_base_id IN
#{knowledgeBaseId}
ORDER BY v.embedding_model_id, v.embedding_provider, v.embedding_model, v.embedding_dimensions

SELECT kb.id AS knowledge_base_id, kb.name AS knowledge_base_name, c.id AS chunk_id, c.document_id, c.version_id, d.name AS document_name, c.chunk_index, c.content, c.heading, v.format, c.source_unit, c.source_start AS line_start, c.source_end AS line_end, 1 - (c.embedding <=> CAST(#{vector} AS vector)) AS similarity FROM document_chunks c JOIN documents d ON d.id = c.document_id AND d.active_version_id = c.version_id JOIN knowledge_bases kb ON kb.id = d.knowledge_base_id JOIN document_versions v ON v.id = c.version_id WHERE v.status IN ('READY', 'PROCESSING') AND EXISTS (SELECT 1 FROM users u WHERE u.id = kb.owner_id AND u.role = 'ADMIN') AND v.embedding_model_id = #{modelId} AND v.embedding_provider = #{provider} AND v.embedding_model = #{model} AND v.embedding_dimensions = #{dimensions} AND d.knowledge_base_id IN
#{knowledgeBaseId}
ORDER BY c.embedding <=> CAST(#{vector} AS vector), c.id LIMIT #{limit}
